<template>
  <div class="row">
    <div
      class="right_section_pdf_view scrolle-y height-100-140px"
      id="image_container"
    >
      <div
        class="full-width img-magnifier-container"
        id="image_scrolle"
        style="position: relative"
      >
        <div class="img-magnifier-glass"></div>

        <img
          class="screenshot"
          :src="image + '?' + tokenQueryParam"
          :width="imageWidth"
          id="screenshot"
          ref="screenshot"
          draggable="false"
          :style="'margin-left:' + imageMarginLeft + 'px'"
          @load="
            imageLoaded = true;
            getImageDetails(true);
          "
        />

        <svg
          :style="'margin-left:' + imageMarginLeft + 'px'"
          :width="imageWidth"
          :height="imageHeight"
          :viewBox="viewBox"
          id="draw"
          ref="draw"
          xmlns="http://www.w3.org/2000/svg"
          style="height: auto; border-bottom: 5px dotted"
        >
          <rect
            id="marquee"
            ref="marquee"
            x="450"
            y="420"
            width="150"
            height="150"
          />
          <g id="boxes" ref="boxes"></g>
        </svg>
      </div>
    </div>

    <div class="max-width-120 scrolle-y" id="left_section" ref="left_section">
      <div class="full-width">
        <div class="column">
          <q-btn flat class="pr-6 pl-6" @click="zoomIn">
            <Icon icon="mdi:magnify-plus" width="24" height="24" />
            <q-tooltip>{{ $t('zoom_in') }}</q-tooltip>
          </q-btn>

          <q-btn flat class="pr-6 pl-6" @click="zoomOut">
            <Icon icon="mdi:magnify-minus" width="24" height="24" />
            <q-tooltip>Zoom Out</q-tooltip>
          </q-btn>
        </div>
        <q-separator />

        <div class="row">
          <div class="page-numbers center-inner">
            {{ currentPage() }}/{{ images.length }}
          </div>
        </div>

        <div class="full-width">
          <img
            v-for="(imageMoc, index) in images"
            :data-id="index"
            :key="index"
            :src="baseUrl + '/' + imageMoc.path + '?' + tokenQueryParam"
            class="q-pa-xs shadow-5 full-width q-ma-sm cursor-pointer"
            :class="index === page - 1 ? 'active' : ''"
            style="height: auto"
            @click="imageclicked"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { useImageAuth } from 'src/composables/useImageAuth';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';

import { DOC2API_URL } from 'src/pages/APIs';
import helperUtil from 'src/utils/helperUtil';
import documentUtil from 'src/utils/documentUtil';
import { tableRowIdPreFix } from 'src/constants';
import ColorGenerator from 'src/utils/ColorGenerator';
import { cleanUpImagesUrl, cleanUpImagePath } from 'src/utils/viewImages';
import {
  MarqueeRectType,
  RectCoordinateType,
  dynamicObj} from 'src/pages/assets';
import validationViewHelper from 'src/pages/ValidationScreen/validation-view-helper';
import {
  useDocumentStore,
  useFormBuilderSettingsStore} from 'src/store/main';

const $ = document.querySelector.bind(document);

export default defineComponent({
  name: 'PdfView',
  mixins: [helperUtil, documentUtil, validationViewHelper, ColorGenerator],
  components: {
    
  },

  data() {
    return {
      isReadOnly: ref(0),
      pdf_in_window: false,
      pdf_data: ref({} as any),
    };
  },
  mounted() {
    this.addEvents();
    window.addEventListener('beforeunload', this.notifyParentOnClose);

    this.init();
    // this reference is beaing used from the parent window
    (<any>window).PdfView = this;
  },
  unmounted() {
    this.removeEvents();
  },
  methods: {
    async init() {
      this.initImageArea();
      await this.setRecordFromCache();
      this.images = cleanUpImagesUrl(this.record.images);

      this.page = opener.FieldsView.page;
      this.image =
        this.baseUrl +
        '/' +
        this.images[this.page - 1].path +
        this.tokenQueryParam;
      this.isReadOnly = opener.FieldsView.isReadOnly;
    },

    getDataFromParent(data: any) {
      if (this[data.key]) {
        this[data.key] = data.value;
      }

      if (data.redraw) {
        this.page = opener.FieldValidationView.page;
        this.restrictDrawing();
        this.getImageDetails();
      }
    },

    getImageDetails(defaultWidth?: boolean) {
      if (defaultWidth) {
        this.imageWidth = document.documentElement.clientHeight * 0.65;
      } else {
        this.imageWidth = this.screenshot.offsetWidth;
      }

      this.centerAligneImage();

      this.$nextTick(() => {
        this.imageHeight = this.screenshot.offsetHeight;
        this.viewBox =
          '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);
        this.removeMagnifier();
        this.prepareRectangles();
      });
    },

    centerAligneImage() {
      let imageElm = $('#image_container') as HTMLElement;
      let imageContainerWidth = imageElm.offsetWidth;

      if (imageContainerWidth > this.imageWidth) {
        this.imageMarginLeft = Math.round(
          (imageContainerWidth - this.imageWidth) / 2,
        );
      }
    },

    imageclicked(evt: any) {
      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(this.record.images[evt.target.dataset.id].path);
      this.page = parseInt(evt.target.dataset.id) + 1;
      opener.FieldValidationView.page = this.page;
      opener.FieldValidationView.image = this.image;
    },

    getOverlayHeadings() {
      return opener.FieldValidationView.getOverlayHeadings() as string;
    },
    getComponentType() {
      this.componentType = opener.FieldValidationView.componentType;
    },
    async getTextByCoordinates(rectCordinate: RectCoordinateType) {
      this.cleanRectangles();
      opener.FieldValidationView.viewBox = this.viewBox;
      opener.FieldValidationView.imageWidth = this.imageWidth;
      opener.FieldValidationView.imageHeight = this.imageHeight;
      await opener.FieldValidationView.getTextByCoordinates(rectCordinate);
    },
    saveOverlayResult() {
      this.cleanRectangles();
      opener.FieldValidationView.viewBox = this.viewBox;
      opener.FieldValidationView.imageWidth = this.imageWidth;
      opener.FieldValidationView.imageHeight = this.imageHeight;
      opener.FieldValidationView.saveResultWrapper(
        this.marqueeRect,
        this.rectCordinate,
      );
    },
    selectNextField(connectionId: string) {
      opener.FieldValidationView.selectNextField(connectionId);
    },
    initTempFieldDelete() {
      opener.FieldValidationView.initTempFieldDelete();
    },
    getFieldByIndex(connectionId: string): any {
      return opener.FieldValidationView.getFieldByIndex(connectionId);
    },
    enableOrDisableExportButton() {
      opener.FieldValidationView.enableOrDisableExportButton();
    },
    refreshCanvas() {
      this.removeBordersFromRectangles();
      this.removeExistingConfirmationOverlays();
      this.getImageDetails();
    },
    showConnectionFromRect(ev: any) {
      this.removeBordersFromRectangles();
      this.removeExistingConfirmationOverlays();
      this.restrictDrawing();
      const connectionId: string = ev.target.getAttribute('connectionId');
      const rectElement = ev.target;
      this.scrollInToViewCenter(rectElement);
      if (!connectionId.startsWith(tableRowIdPreFix)) {
        this.drawOverlay(connectionId, rectElement);
      }
      rectElement.classList.add('svg-stroke-border');
      opener.FieldValidationView.dsiplayFieldInToView(connectionId);
    },
    proceedForReactFinding(
      connectionId: string,
      fieldElement: Element,
      isTableRow: boolean,
    ) {
      // Duplicate-coords rows share one drawn rect; resolve to it (see aiRowRectMap).
      const rectId = (this.aiRowRectMap && this.aiRowRectMap[connectionId]) || connectionId;
      let rectElement = $('#' + rectId + '_rect');
      if (rectElement) {
        this.scrollInToViewCenter(rectElement as HTMLElement);
      }
      setTimeout(() => {
        if (isTableRow) {
          this.highlightRow(rectElement);
          return;
        }

        if (!rectElement) {
          opener.FieldValidationView.proceedIfReactNotFound(fieldElement);
          return;
        }
        this.drawOverlay(connectionId, rectElement);
        // Adding border to corresponding rectangle
        rectElement.classList.add('svg-stroke-border');
      }, 50);
    },
    getHTMLField(field: any): any {
      return opener.FieldValidationView.getHTMLField(field);
    },
    zoomOut() {
      if (this.imageWidth > 200) {
        this.imageWidth = this.imageWidth - 100;
        setTimeout(() => {
          this.getImageDetails();
        }, 10);
      }
    },
    zoomIn() {
      this.imageWidth = this.imageWidth + 100;
      setTimeout(() => {
        this.getImageDetails();
      }, 10);
    },
    notifyParentOnClose() {
      if (opener.FieldValidationView) {
        opener.FieldValidationView.closeExternalWindow();
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, has_ai_table } = storeToRefs(doc_store);
    const { setRecordFromCache } = doc_store;

    const form_builder_settings_store = useFormBuilderSettingsStore();
    const { isConfirmationBoxDisable } = storeToRefs(
      form_builder_settings_store,
    );

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    let rectangles: MarqueeRectType[] = [];

    let rectCordinate: RectCoordinateType = {
      startX: 0,
      startY: 0,
      endX: 0,
      endY: 0,
    };

    const marqueeRect: MarqueeRectType = {
      x: 0,
      y: 0,
      width: 0,
      height: 0,
      connectionId: '',
    };
    // Temp variables
    let startX = 0;
    let startY = 0;

    // Template refs - Vue will auto-bind these to DOM elements
    const screenshot = ref<HTMLElement | null>(null);
    const marquee = ref<HTMLElement | null>(null);
    const boxes = ref<HTMLElement | null>(null);

    return {
      tokenQueryParam,
      image: ref(''),
      imageWidth: ref(460),
      imageHeight: ref(0),
      imageLoaded: ref(false),
      imageMarginLeft: ref(0),
      viewBox: ref('0 0 0 0'),
      magnifyGlass: {} as any,
      isConfirmationBoxDisable,

      images: [] as any,
      page: ref(1),

      record,
      has_ai_table,
      rectCordinate: rectCordinate,
      marqueeRect: marqueeRect,
      screenshot,
      rectangles: rectangles,
      marquee,
      startX: startX,
      startY: startY,
      boxes,
      componentType: 'input',
      baseUrl: DOC2API_URL,
      field_view_mode: ref('validate'),

      setRecordFromCache,
    };
  },
});
</script>

<style scoped lang="scss">
.height-100-140px {
  height: calc(100vh - 50px);
}
.right_section_pdf_view {
  width: calc(100vw - 150px);
}
</style>
